import { InvalidTransitionError, ValidationError } from "./errors";
import { assertPositiveInteger } from "./product";

export const ORDER_STATES = [
  "placed",
  "paid",
  "packed",
  "shipped",
  "delivered",
  "cancelled",
] as const;

export type OrderState = (typeof ORDER_STATES)[number];

/** The forward-only fulfilment sequence; each state may only advance to the next. */
const FULFILMENT_SEQUENCE: readonly OrderState[] = [
  "placed",
  "paid",
  "packed",
  "shipped",
  "delivered",
];

const CANCELLABLE_STATES: ReadonlySet<OrderState> = new Set<OrderState>([
  "placed",
  "paid",
  "packed",
]);

export function isOrderState(value: string): value is OrderState {
  return (ORDER_STATES as readonly string[]).includes(value);
}

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
  readonly unitPriceCents: number;
}

export interface StateChange {
  readonly state: OrderState;
  readonly at: Date;
}

export interface OrderSnapshot {
  readonly id: string;
  readonly customerId: string;
  readonly lines: readonly OrderLine[];
  readonly totalCents: number;
  readonly state: OrderState;
  readonly history: readonly StateChange[];
  readonly createdAt: string;
  readonly updatedAt: string;
}

export class Order {
  private _state: OrderState = "placed";
  private readonly _history: StateChange[];

  constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly lines: readonly OrderLine[],
    public readonly createdAt: Date,
  ) {
    if (!customerId) throw new ValidationError("customerId is required");
    if (lines.length === 0) throw new ValidationError("An order must have at least one line");
    const seen = new Set<string>();
    for (const line of lines) {
      assertPositiveInteger(line.quantity, "quantity");
      if (seen.has(line.productId)) {
        throw new ValidationError(`Duplicate line for product ${line.productId}`);
      }
      seen.add(line.productId);
    }
    this._history = [{ state: "placed", at: createdAt }];
  }

  get state(): OrderState {
    return this._state;
  }

  get history(): readonly StateChange[] {
    return this._history;
  }

  get totalCents(): number {
    return this.lines.reduce((sum, l) => sum + l.quantity * l.unitPriceCents, 0);
  }

  /** The state this order may advance to next, or undefined if it is terminal. */
  nextState(): OrderState | undefined {
    const index = FULFILMENT_SEQUENCE.indexOf(this._state);
    if (index < 0 || index === FULFILMENT_SEQUENCE.length - 1) return undefined;
    return FULFILMENT_SEQUENCE[index + 1];
  }

  canCancel(): boolean {
    return CANCELLABLE_STATES.has(this._state);
  }

  transitionTo(target: OrderState, at: Date): void {
    if (target === "cancelled") {
      if (!this.canCancel()) {
        throw new InvalidTransitionError(
          `Order ${this.id} cannot be cancelled in state '${this._state}'`,
        );
      }
    } else if (this.nextState() !== target) {
      throw new InvalidTransitionError(
        `Order ${this.id} cannot move from '${this._state}' to '${target}'`,
      );
    }
    this._state = target;
    this._history.push({ state: target, at });
  }

  toSnapshot(): OrderSnapshot {
    const last = this._history[this._history.length - 1];
    return {
      id: this.id,
      customerId: this.customerId,
      lines: this.lines.map((l) => ({ ...l })),
      totalCents: this.totalCents,
      state: this._state,
      history: this._history.map((h) => ({ ...h })),
      createdAt: this.createdAt.toISOString(),
      updatedAt: (last ? last.at : this.createdAt).toISOString(),
    };
  }
}

