import { InsufficientStockError, ValidationError } from "./errors";

export interface ProductSnapshot {
  readonly id: string;
  readonly name: string;
  readonly priceCents: number;
  readonly onHand: number;
  readonly reserved: number;
  readonly available: number;
}

/**
 * A catalogue product with its stock level.
 * `onHand` is physical stock in the warehouse; `reserved` is the portion
 * held for orders that have not yet shipped.
 */
export class Product {
  private _onHand: number;
  private _reserved = 0;

  constructor(
    public readonly id: string,
    public readonly name: string,
    public readonly priceCents: number,
    onHand: number,
  ) {
    if (!id) throw new ValidationError("Product id is required");
    if (!name) throw new ValidationError("Product name is required");
    assertNonNegativeInteger(priceCents, "priceCents");
    assertNonNegativeInteger(onHand, "onHand");
    this._onHand = onHand;
  }

  get onHand(): number {
    return this._onHand;
  }

  get reserved(): number {
    return this._reserved;
  }

  get available(): number {
    return this._onHand - this._reserved;
  }

  canReserve(quantity: number): boolean {
    return quantity <= this.available;
  }

  reserve(quantity: number): void {
    assertPositiveInteger(quantity, "quantity");
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError(this.id, quantity, this.available);
    }
    this._reserved += quantity;
  }

  release(quantity: number): void {
    assertPositiveInteger(quantity, "quantity");
    if (quantity > this._reserved) {
      throw new ValidationError(`Cannot release more than reserved for product ${this.id}`);
    }
    this._reserved -= quantity;
  }

  /** Reserved stock leaves the warehouse when the order ships. */
  ship(quantity: number): void {
    assertPositiveInteger(quantity, "quantity");
    if (quantity > this._reserved) {
      throw new ValidationError(`Cannot ship more than reserved for product ${this.id}`);
    }
    this._reserved -= quantity;
    this._onHand -= quantity;
  }

  restock(quantity: number): void {
    assertPositiveInteger(quantity, "quantity");
    this._onHand += quantity;
  }

  toSnapshot(): ProductSnapshot {
    return {
      id: this.id,
      name: this.name,
      priceCents: this.priceCents,
      onHand: this._onHand,
      reserved: this._reserved,
      available: this.available,
    };
  }
}

export function assertPositiveInteger(value: number, field: string): void {
  if (!Number.isInteger(value) || value <= 0) {
    throw new ValidationError(`${field} must be a positive integer`);
  }
}

export function assertNonNegativeInteger(value: number, field: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new ValidationError(`${field} must be a non-negative integer`);
  }
}

